        let cur_idx = match pre.combiner[node_id] {
            CombinerState::Appending { cur_idx, .. } => cur_idx,
            _ => 0,
        };
        let tail = match pre.combiner[node_id] {
            CombinerState::Appending { tail, .. } => tail,
            _ => 0,
        };
        assert(pre.combiner[node_id].is_Appending());

        assert forall |n| post.combiner.contains_key(n) implies post.combiner_valid(n, post.combiner[n]) by {
            if n == node_id {
                assert(pre.combiner_valid(n, pre.combiner[n]));
                assert(pre.local_versions[node_id] <= cur_idx);
                assert(cur_idx <= tail);
                assert(tail <= pre.tail);
                assert((pre.tail as int) - (pre.buffer_size as int) <= cur_idx);
                assert(cur_idx < tail);
                assert(cur_idx + 1 <= tail);
                assert(cur_idx + 1 <= post.tail);
                assert((post.tail as int) - (post.buffer_size as int) <= cur_idx + 1);
                assert forall |i: nat| cur_idx + 1 <= i < tail implies
                    !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    assert(cur_idx <= i < cur_idx + pre.buffer_size);
                    log_entry_idx_wrap_around(cur_idx, pre.buffer_size, i);
                    assert(log_entry_idx(i as int, pre.buffer_size) != log_entry_idx(cur_idx as int, pre.buffer_size));
                    assert(post.alive_bits[log_entry_idx(i as int, pre.buffer_size)] ===
                        pre.alive_bits[log_entry_idx(i as int, pre.buffer_size)]);
                    assert(!log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
